1	//! A checker type converted to [`PropType`] from the checker's structured answers: type flags, a union's members, a
2	//! reference's type arguments, a tuple's element flags, an object's properties, index and call signatures, an alias's
3	//! symbol and arguments. The printed type (`typeToString`) names things for display and for the two facts the
4	//! structure does not state (see [`crate::printed`]); no shape is read from it.
5	//!
6	//! The conversion of a type is a function of the type, how deep it sits and which instantiations enclose it, never of
7	//! the order the checker was asked in, so the memo can be keyed by the checker's type handle (valid inside one
8	//! snapshot) without making the output depend on query order. A handle is also what tells one instantiation from
9	//! another while a type is being expanded (`Box<Box<string>>` is two instantiations of one declaration): only its
10	//! equality is read, inside one conversion, so the answer does not depend on the numbers. The recursion marker that
11	//! results is named by the declaration (the alias or interface) and holds no handle. The memo is keyed by the enclosing
12	//! instantiations a conversion actually asked about, not by all of them (see [`State::memo`]).
13	//!
14	//! Every descent into the parts of a type (members, properties, elements, holes) passes [`Converter::enter`], which
15	//! decides before anything is fetched or converted whether the type is an enclosing instantiation (a back-reference),
16	//! sits too deep, or is too wide.
17	//!
18	//! What stays a name instead of an expansion, the named boundary: an object type declared in a dependency
19	//! (`node_modules`) or an interface or class of the TypeScript lib (`Date`, `HTMLElement`, `Promise<T>`), with its type
20	//! arguments; a function type is always expanded, since its parameters are what a reader wants. The lib's type-level
21	//! utilities (`Partial`, `Pick`, `Omit`, `Record`) are evaluated, not named: their result is the type, unless it is
22	//! wider than the budget and what it applies to has a name (see [`Converter::over_budget`]). A dependency's union of
23	//! literals is expanded too, since its members are the values a control offers. What the caps cut is a typed
24	//! [`PropType::Truncated`], never the checker's text standing in as a name. The width of an object counts only the
25	//! members the project did not declare: its own are listed whole.
26	
27	use std::future::Future;
28	use std::pin::Pin;
29	use std::sync::atomic::{AtomicU64, Ordering};
30	use std::sync::{Arc, Mutex};
31	
32	use caliper_docgen_core::react_types::{html_element_for, html_element_from_type_arg, is_intrinsic_tag};
33	use caliper_docgen_core::types::semantic::{degraded_type, unresolved_type};
34	use caliper_docgen_core::types::{
35	    BigIntValue, CallSignature, EnumMemberValue, FunctionParam, ObjectField, OpaqueReason, PropType,
36	    SignatureKind as Kind, TemplatePart, TruncationLimit, TupleElement, TupleElementKind, TupleLabel,
37	};
38	use rustc_hash::FxHashMap;
39	
40	use crate::declared::Declared;
41	use crate::printed::{Marker, SignatureMarkers, signature_markers, tuple_labels};
42	use crate::rpc::{
43	    CallError, CompactSymbol, ObjectMembers, Rpc, SignatureInfo, SignatureKind, SymbolInfo, TypeInfo, decode, flag,
44	};
45	use serde_json::value::RawValue;
46	
47	/// Nesting past which an object, union or intersection is cut with [`TruncationLimit::Depth`].
48	const MAX_DEPTH: u8 = 5;
49	/// The most properties an object type lists at the top (a prop's own type) and below it that the project did not declare
50	/// itself (see [`is_own`]): what it declared is never cut.
51	const MAX_FIELDS: [usize; 2] = [100, 40];
52	/// The most members a union or intersection lists at the top and below it.
53	const MAX_MEMBERS: [usize; 2] = [500, 120];
54	/// How many of React's tag names (see [`is_tag`]) a union has to list to be React's `ElementType` (`JSX.IntrinsicElements`
55	/// has over 170): the tag names are the one part of it that no declaration identifies.
56	const MIN_INTRINSIC_TAGS: usize = 100;
57	/// The lib's utility aliases that keep the properties of the type they are applied to, and so can stand for it.
58	const UTILITIES: [&str; 5] = ["Omit", "Pick", "Partial", "Required", "Readonly"];
59	
60	/// What a descent found at [`Converter::enter`].
61	enum Gate<T> {
62	    /// The type is not expanded: it is a back-reference, or a cap cut it.
63	    Stop(PropType),
64	    /// The parts of the type, and the context to convert them in.
65	    Open { parts: T, inner: Cx },
66	}
67	
68	type Converted<'a> = Pin<Box<dyn Future<Output = Result<PropType, CallError>> + Send + 'a>>;
69	
70	/// Where a type sits: how deep, and which named instantiations (an alias or interface with its type arguments, as the
71	/// checker's type handle) enclose it, outermost first.
72	#[derive(Debug, Clone, Default)]
73	pub(crate) struct Cx {
74	    depth: u8,
75	    enclosing: Arc<Vec<u64>>,
76	    /// The conversion this context belongs to, which records which enclosing instantiations it asks about. `None` at
77	    /// the roots.
78	    frame: Option<Arc<Frame>>,
79	}
80	
81	/// What one conversion has asked of the instantiations enclosing it, kept to build its memo entry (see
82	/// [`State::memo`]).
83	#[derive(Debug)]
84	struct Frame {
85	    /// How many instantiations enclosed the type when its conversion began: those below this are the outer context, the
86	    /// rest were opened by the conversion itself.
87	    base: usize,
88	    asked: Mutex<Asked>,
89	}
90	
91	#[derive(Debug, Default)]
92	struct Asked {
93	    /// The handles this conversion's own gate compared against its enclosing instantiations.
94	    ids: Vec<u64>,
95	    /// The sets asked by the conversions of its parts, each with the instantiations this conversion had opened by then:
96	    /// those were answered inside it and do not depend on its outer context.
97	    parts: Vec<(Arc<[u64]>, Vec<u64>)>,
98	}
99	
100	impl Frame {
101	    fn new(base: usize) -> Self {
102	        Frame { base, asked: Mutex::default() }
103	    }
104	
105	    fn lock(&self) -> std::sync::MutexGuard<'_, Asked> {
106	        self.asked.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
107	    }
108	
109	    fn ask(&self, id: u64) {
110	        self.lock().ids.push(id);
111	    }
112	
113	    /// A part of this conversion was converted (or recalled) under `enclosing`, having asked about `asked`.
114	    fn absorb(&self, asked: &Arc<[u64]>, enclosing: &[u64]) {
115	        if !asked.is_empty() {
116	            self.lock().parts.push((asked.clone(), enclosing.get(self.base..).unwrap_or_default().to_vec()));
117	        }
118	    }
119	
120	    /// Every handle the conversion asked about whose answer came from outside it: sorted, once each.
121	    fn finish(&self) -> Arc<[u64]> {
122	        let asked = self.lock();
123	        let mut ids = asked.ids.clone();
124	        for (part, opened) in &asked.parts {
125	            ids.extend(part.iter().copied().filter(|id| !opened.contains(id)));
126	        }
127	        ids.sort_unstable();
128	        ids.dedup();
129	        ids.into()
130	    }
131	}
132	
133	impl Cx {
134	    /// The context of what a name carries, its type arguments: one level down. Each argument is converted on its own
135	    /// and passes [`Converter::enter`] if it has parts.
136	    fn argument(&self) -> Cx {
137	        Cx { depth: self.depth.saturating_add(1), enclosing: self.enclosing.clone(), frame: self.frame.clone() }
138	    }
139	
140	    /// The context of the parts of a type that [`Converter::enter`] has admitted. Only a named instance is kept, since
141	    /// only a name can be pointed back to.
142	    fn below(&self, instance: Option<u64>) -> Cx {
143	        let mut enclosing = self.enclosing.clone();
144	        if let Some(id) = instance
145	            && !enclosing.contains(&id)
146	        {
147	            let mut grown = (*enclosing).clone();
148	            grown.push(id);
149	            enclosing = Arc::new(grown);
150	        }
151	        Cx { depth: self.depth.saturating_add(1), enclosing, frame: self.frame.clone() }
152	    }
153	
154	    /// Whether `id` is an instantiation being expanded around the type. The conversion in progress is recorded to have
155	    /// asked, whichever the answer.
156	    fn encloses(&self, id: u64) -> bool {
157	        if let Some(frame) = &self.frame {
158	            frame.ask(id);
159	        }
160	        self.enclosing.contains(&id)
161	    }
162	
163	    fn limit<const N: usize>(&self, limits: [usize; N]) -> usize {
164	        limits[usize::from(self.depth > 0).min(N - 1)]
165	    }
166	}
