168	/// What declares a type: the alias it was written through, else its interface or class.
169	#[derive(Debug, Clone)]
170	struct Origin {
171	    name: String,
172	    /// The declaring file as the checker keys it (lower-cased path).
173	    file: String,
174	    alias: bool,
175	}
176	
177	impl Origin {
178	    fn of(symbol: &SymbolInfo, alias: bool) -> Self {
179	        let declaration = symbol.declarations.first().map(String::as_str);
180	        Origin {
181	            name: symbol.name.clone(),
182	            file: declaration.map(|declaration| declared_in(declaration).to_string()).unwrap_or_default(),
183	            alias,
184	        }
185	    }
186	
187	    fn in_dependency(&self) -> bool {
188	        file_in_dependency(&self.file)
189	    }
190	
191	    fn in_lib(&self) -> bool {
192	        file_in_lib(&self.file)
193	    }
194	
195	    fn in_react(&self) -> bool {
196	        self.file.contains("/@types/react/")
197	    }
198	
199	    /// Whether the name stands for the type: declared in a dependency, or an interface or class of the lib. An alias
200	    /// of the lib is a type-level function (`Partial<T>`), and its result is the type.
201	    fn is_boundary(&self) -> bool {
202	        // The lib may itself sit under `node_modules` (`typescript/lib`, `@tsrs/<platform>`).
203	        if self.in_lib() { !self.alias } else { self.in_dependency() }
204	    }
205	
206	    /// The React type that PropType holds as a terminal, found by the declaration and not by how it prints.
207	    fn react_terminal(&self) -> Option<PropType> {
208	        if !self.in_react() {
209	            return None;
210	        }
211	        match (self.name.as_str(), self.alias) {
212	            ("ReactNode", true) | ("ReactElement" | "Element", false) => Some(PropType::ReactNode),
213	            ("ElementType", true) => Some(PropType::ElementType),
214	            ("CSSProperties", false) => Some(PropType::CssProperties),
215	            _ => None,
