220	/// Whether a union member is a tag of React's `JSX.IntrinsicElements`: a string literal (not an enum member) whose value
221	/// that table lists. A literal the checker gave no value for is not one, so it is kept beside the terminal.
222	fn is_tag(member: &TypeInfo) -> bool {
223	    member.flags & flag::STRING_LITERAL != 0
224	        && member.flags & flag::ENUM_LITERAL == 0
225	        && member.value.as_ref().and_then(|value| value.as_str()).is_some_and(is_intrinsic_tag)
226	}
