228	/// Whether the checker states the base types of this type in its own terms: the declaration of a class or interface
229	/// does. An instantiation of a generic one (`Box<string>`, only a reference) does not state them in terms of its
230	/// arguments, so a traversal that keeps the arguments cannot list what it inherits; one that wants only names reads the
231	/// generic type instead ([`Converter::named_bases`]).
232	fn states_bases(info: &TypeInfo) -> bool {
233	    info.object_flags & (flag::OBJECT_CLASS | flag::OBJECT_INTERFACE) != 0
234	}
235	
236	/// Where the base types of a type are to be asked, from what the checker says of the type itself.
237	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
238	enum BasesOf {
239	    /// A class or interface declaration: the checker states them ([`states_bases`]).
240	    Itself,
241	    /// An instantiation of a generic type: its generic target states them.
242	    Generic,
243	    /// An object type no class or interface declares (a type literal, a mapped type): it has none.
244	    None,
245	    /// A union, a type parameter or any other type the checker was not asked about: whether it has bases is not known.
246	    Unknown,
247	}
248	
249	impl BasesOf {
250	    fn of(info: &TypeInfo) -> Self {
251	        if states_bases(info) {
252	            Self::Itself
253	        } else if info.object_flags & flag::OBJECT_REFERENCE != 0 {
254	            Self::Generic
255	        } else if info.flags & flag::OBJECT != 0 {
256	            Self::None
257	        } else {
258	            Self::Unknown
259	        }
260	    }
261	}
