263	fn file_in_dependency(file: &str) -> bool {
264	    file.contains("/node_modules/")
265	}
266	
267	fn file_in_lib(file: &str) -> bool {
268	    let name = file.rsplit('/').next().unwrap_or("");
269	    name.starts_with("lib.") && name.ends_with(".d.ts")
270	}
271	
272	/// Whether a property is the project's own: its first declaration is in a file of the project, not a dependency or the
273	/// lib. A property with no declaration (a mapped type's synthetic one) is not, so a wide mapped type is still cut.
274	fn is_own(property: &SymbolInfo) -> bool {
275	    property.declarations.first().is_some_and(|declaration| {
276	        let file = declared_in(declaration);
277	        !file_in_dependency(file) && !file_in_lib(file)
278	    })
279	}
