281	/// `declarations` entries read `"<node index>.<kind>.<path>"`: the path is lower-cased, as the checker keys files.
282	pub(crate) fn declared_in(declaration: &str) -> &str {
283	    declaration.splitn(3, '.').nth(2).unwrap_or("")
284	}
