286	/// A converted type, with the enclosing instantiations its conversion depended on.
287	#[derive(Debug)]
288	struct Entry {
289	    /// Every handle the conversion compared against the instantiations enclosing it, sorted.
290	    asked: Arc<[u64]>,
291	    /// Those of `asked` that did enclose it.
292	    enclosed_by: Vec<u64>,
293	    converted: PropType,
294	}
295	
296	impl Entry {
297	    /// Whether the conversion would go the same way inside `enclosing`: among the handles it asked about, the ones
298	    /// that enclose the type there are exactly `enclosed_by`.
299	    fn holds_in(&self, enclosing: &[u64]) -> bool {
300	        self.enclosed_by.iter().all(|id| enclosing.contains(id))
301	            && enclosing.iter().all(|id| self.enclosed_by.contains(id) || self.asked.binary_search(id).is_err())
302	    }
303	}
304	
305	type Memo = Mutex<FxHashMap<(u64, u8), Vec<Arc<Entry>>>>;
306	
307	/// The parts of each type asked about so far, by (type handle, which parts), as the text the checker answered: read
308	/// again on each use, which costs a fraction of the round trip, and is several times smaller than the read lists.
309	type PartsSeen = Mutex<FxHashMap<(u64, Parts), Arc<RawValue>>>;
310	
311	/// Which parts of a type [`Converter::parts`] asks for.
312	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
313	enum Parts {
314	    /// A union's, intersection's or template literal's members (`getTypesOfType`).
315	    Members,
316	    /// A reference's type arguments (`getTypeArguments`), the `this` type the checker appends included.
317	    Arguments,
318	}
319	
320	/// The type arguments a reference names, without the `this` type the checker appends to a class's or interface's.
321	fn without_this(arguments: &[TypeInfo]) -> &[TypeInfo] {
322	    let named = arguments.iter().rposition(|argument| !argument.is_this_type).map_or(0, |last| last + 1);
323	    arguments.get(..named).unwrap_or_default()
324	}
