359	pub(crate) struct Converter {
360	    rpc: Arc<Rpc>,
361	    state: Arc<State>,
362	    /// Ask the checker about the members of a type last to first. The answer is the same, and a test holds it to that.
363	    reverse: bool,
364	}
365	
366	impl Converter {
367	    pub(crate) fn new(rpc: Arc<Rpc>, reverse: bool) -> Self {
368	        Self { rpc, state: Arc::new(State::default()), reverse }
369	    }
370	
371	    /// Every type converted, in the order of `infos`, though when `reverse` is set the checker is asked last to first.
372	    async fn convert_all(&self, infos: &[TypeInfo], cx: &Cx) -> Result<Vec<PropType>, CallError> {
373	        let mut slots: Vec<Option<PropType>> = vec![None; infos.len()];
374	        let order: Box<dyn Iterator<Item = usize> + Send> =
375	            if self.reverse { Box::new((0..infos.len()).rev()) } else { Box::new(0..infos.len()) };
376	        for index in order {
377	            if let (Some(info), Some(slot)) = (infos.get(index), slots.get_mut(index)) {
378	                *slot = Some(self.convert(info, cx).await?);
379	            }
380	        }
381	        Ok(slots.into_iter().flatten().collect())
382	    }
