384	    /// Memo hits and misses so far, for the debug line.
385	    pub(crate) fn memo_stats(&self) -> (u64, u64) {
386	        (self.state.hits.load(Ordering::Relaxed), self.state.misses.load(Ordering::Relaxed))
387	    }
388	
389	    /// The own types of a component's props, from the top.
390	    pub(crate) async fn convert_roots(&self, infos: &[TypeInfo]) -> Result<Vec<PropType>, CallError> {
391	        self.convert_all(infos, &Cx::default()).await
392	    }
393	
394	    /// Where each prop of `asked` is declared and what its JSDoc says ([`crate::declared`]).
395	    pub(crate) async fn declared(&self, asked: &[crate::declared::Asked<'_>]) -> Result<Vec<Declared>, CallError> {
396	        crate::declared::declared(&self.rpc, &self.state.declared, asked).await
397	    }
398	
399	    /// The `@types/react` types a props type is made of, by name, in the order it names them: its bases and the members
400	    /// of an intersection, seen through the project's and dependencies' own types and through a lib utility (`Omit`,
401	    /// `Pick`) to what it applies to. A React type is found by where it is declared, as [`Origin::react_terminal`]
402	    /// finds React's terminals, and is not looked into. `None` when a type on the way has bases the checker cannot be
403	    /// asked for ([`Self::named_bases`]): the list would not be the answer, and an empty one would say there are none.
404	    pub(crate) async fn composes(&self, props_type: &TypeInfo) -> Result<Option<Vec<String>>, CallError> {
405	        let mut names: Vec<String> = Vec::new();
406	        let mut seen: Vec<u64> = Vec::new();
407	        let mut pending = vec![props_type.clone()];
408	        while let Some(info) = pending.pop() {
409	            if seen.contains(&info.id) {
410	                continue;
411	            }
412	            seen.push(info.id);
413	            let origin = self.origin(&info).await?;
414	            if let Some(origin) = &origin {
415	                if origin.in_react() {
416	                    if !names.contains(&origin.name) {
417	                        names.push(origin.name.clone());
418	                    }
419	                    continue;
420	                }
421	                if origin.alias && origin.in_lib() && UTILITIES.contains(&origin.name.as_str()) {
422	                    pending.extend(self.rpc.alias_type_arguments(info.id).await?.into_iter().take(1));
423	                    continue;
424	                }
425	            }
426	            let parts = if info.flags & flag::INTERSECTION != 0 {
427	                self.parts(info.id, Parts::Members).await?
428	            } else {
429	                let Some(bases) = self.named_bases(&info).await? else { return Ok(None) };
430	                bases
431	            };
432	            // Last first onto the stack, so they are taken in the order the type names them.
433	            pending.extend(parts.into_iter().rev());
434	        }
435	        Ok(Some(names))
436	    }
437	
438	    /// The base types of `info` for a traversal that wants their names and not their arguments. The checker states the
439	    /// bases of the declaration of a class or interface; an instantiation of a generic one (`Props<string>`, only a
440	    /// reference) has none of its own, so they are read from the generic type it instantiates, which names the same
441	    /// types over its own type parameters. `None` when the checker cannot be asked ([`BasesOf::Unknown`]). A traversal
442	    /// that keeps the arguments of what it finds ([`Self::base_layers`]) cannot read them this way, since
443	    /// `HTMLAttributes<T>` is not `HTMLAttributes<HTMLDivElement>`, and tests [`states_bases`] of the type itself.
444	    async fn named_bases(&self, info: &TypeInfo) -> Result<Option<Vec<TypeInfo>>, CallError> {
445	        match BasesOf::of(info) {
446	            BasesOf::Itself => Ok(Some(self.rpc.base_types(info.id).await?)),
447	            BasesOf::Generic => {
448	                let target = self.rpc.target_of_type(info.id).await?;
449	                match BasesOf::of(&target) {
450	                    BasesOf::Itself => Ok(Some(self.rpc.base_types(target.id).await?)),
451	                    _ => Ok(info.is_tuple_type.then(Vec::new)),
452	                }
453	            }
454	            BasesOf::None => Ok(Some(Vec::new())),
455	            BasesOf::Unknown => Ok(None),
456	        }
457	    }
458	
459	    fn convert<'a>(&'a self, info: &'a TypeInfo, cx: &'a Cx) -> Converted<'a> {
460	        Box::pin(async move {
461	            if let Some(entry) = self.recall(info.id, cx) {
462	                self.state.hits.fetch_add(1, Ordering::Relaxed);
463	                if let Some(frame) = &cx.frame {
464	                    frame.absorb(&entry.asked, &cx.enclosing);
465	                }
466	                return Ok(entry.converted.clone());
467	            }
468	            self.state.misses.fetch_add(1, Ordering::Relaxed);
469	            let frame = Arc::new(Frame::new(cx.enclosing.len()));
470	            let own = Cx { depth: cx.depth, enclosing: cx.enclosing.clone(), frame: Some(frame.clone()) };
471	            let converted = self.uncached(info, &own).await?;
472	            let asked = frame.finish();
473	            if let Some(parent) = &cx.frame {
474	                parent.absorb(&asked, &cx.enclosing);
475	            }
476	            let enclosed_by = cx.enclosing.iter().copied().filter(|id| asked.binary_search(id).is_ok()).collect();
477	            let entry = Arc::new(Entry { asked, enclosed_by, converted: converted.clone() });
478	            if let Ok(mut memo) = self.state.memo.lock() {
479	                memo.entry((info.id, cx.depth)).or_default().push(entry);
480	            }
481	            Ok(converted)
482	        })
483	    }
484	
485	    /// The entry for the type at this depth that holds inside the instantiations enclosing it, if there is one.
486	    fn recall(&self, id: u64, cx: &Cx) -> Option<Arc<Entry>> {
487	        let memo = self.state.memo.lock().ok()?;
488	        memo.get(&(id, cx.depth))?.iter().find(|entry| entry.holds_in(&cx.enclosing)).cloned()
489	    }
