301	impl Rpc {
302	    pub(crate) async fn open(
303	        client: Client,
304	        deadline: Duration,
305	        tsconfig: Option<&str>,
306	        root_files: &[String],
307	        record: bool,
308	    ) -> Result<Rpc, CallError> {
309	        let options = Rpc::prepare(&client, deadline, tsconfig).await?;
310	        Rpc::open_with(client, deadline, &options, root_files, record).await
311	    }
312	
313	    /// Initializes the `tsc` session and reads the compiler options, once per process. The beta panics on
314	    /// string-valued enum options such as `target: "es2022"`, so options come from `parseConfigFile`, which yields
315	    /// numeric ones.
316	    pub(crate) async fn prepare(
317	        client: &Client,
318	        deadline: Duration,
319	        tsconfig: Option<&str>,
320	    ) -> Result<Value, CallError> {
321	        let rpc = Rpc {
322	            client: client.clone(),
323	            deadline,
324	            snapshot: 0,
325	            project: String::new(),
326	            options: Value::Null,
327	            recording: None,
328	            calls: Arc::default(),
329	        };
330	        rpc.call("initialize", Value::Null).await?;
331	        Ok(match tsconfig {
332	            Some(file) => {
333	                let parsed: Value = decode(&rpc.call("parseConfigFile", json!({ "file": file })).await?)?;
334	                parsed.get("options").cloned().unwrap_or_else(default_options)
335	            }
336	            None => default_options(),
337	        })
338	    }
339	
340	    /// A snapshot over `root_files` in a session [`Rpc::prepare`] already initialized.
341	    pub(crate) async fn open_with(
342	        client: Client,
343	        deadline: Duration,
344	        options: &Value,
345	        root_files: &[String],
346	        record: bool,
347	    ) -> Result<Rpc, CallError> {
348	        let rpc = Rpc {
349	            client,
350	            deadline,
351	            snapshot: 0,
352	            project: String::new(),
353	            options: options.clone(),
354	            recording: record.then(Arc::default),
355	            calls: Arc::default(),
356	        };
357	        rpc.created(json!({ "createPrograms": [{ "rootFiles": root_files, "compilerOptions": options }] })).await
358	    }
359	
360	    /// A new snapshot of the same program with `files` added, held in the checker's memory and never written to disk:
361	    /// each is a root file, keyed by its absolute path. The calls on it count, and are recorded, with this one's.
362	    pub(crate) async fn layered(&self, root_files: &[String], files: &[(String, String)]) -> Result<Rpc, CallError> {
363	        let rpc = Rpc {
364	            client: self.client.clone(),
365	            deadline: self.deadline,
366	            snapshot: 0,
367	            project: String::new(),
368	            options: self.options.clone(),
369	            recording: self.recording.clone(),
370	            calls: self.calls.clone(),
371	        };
372	        let mut roots = root_files.to_vec();
373	        roots.extend(files.iter().map(|(path, _)| path.clone()));
374	        let layer: serde_json::Map<String, Value> =
375	            files.iter().map(|(path, text)| (path.clone(), Value::String(text.clone()))).collect();
376	        rpc.created(json!({
377	            "fileSystem": { "kind": "layer", "files": layer },
378	            "createPrograms": [{ "rootFiles": roots, "compilerOptions": self.options }],
379	        }))
380	        .await
381	    }
382	
383	    /// The snapshot after this one with `changed` and `deleted` read again from the disk and, given `roots`, its program
384	    /// rooted there instead, built at once (`updateSnapshot` with `ensurePrograms`). Files the program has not changed
385	    /// are kept as parsed: the checker re-reads only what it is told about, and a synthetic program sees even that
386	    /// only when it is rebuilt. This snapshot stays alive until it is released.
387	    pub(crate) async fn updated(
388	        &self,
389	        changed: &[String],
390	        deleted: &[String],
391	        roots: Option<&[String]>,
392	    ) -> Result<Rpc, CallError> {
393	        let mut changes = serde_json::Map::new();
394	        if !changed.is_empty() || !deleted.is_empty() {
395	            changes.insert("fileNotifications".to_string(), json!({ "changed": changed, "deleted": deleted }));
396	        }
397	        if let Some(roots) = roots {
398	            changes.insert(
399	                "reconfigurePrograms".to_string(),
400	                json!([{ "id": self.project, "rootFiles": roots, "compilerOptions": self.options }]),
401	            );
402	        }
403	        changes.insert("ensurePrograms".to_string(), Value::Bool(true));
404	        let response: SnapshotResponse =
405	            decode(&self.call("updateSnapshot", json!({ "snapshot": self.snapshot, "changes": changes })).await?)?;
406	        // The response lists only the projects it replaced; the synthetic program keeps its id.
407	        let project = response.projects.into_iter().next().map_or_else(|| self.project.clone(), |project| project.id);
408	        Ok(Rpc {
409	            client: self.client.clone(),
410	            deadline: self.deadline,
411	            snapshot: response.snapshot,
412	            project,
413	            options: self.options.clone(),
414	            recording: self.recording.clone(),
415	            calls: Arc::default(),
416	        })
417	    }
418	
419	    /// Every file the snapshot's program read, as the checker names them.
420	    pub(crate) async fn source_file_names(&self) -> Result<Vec<String>, CallError> {
421	        self.scoped("getSourceFileNames", json!({})).await
422	    }
423	
424	    /// This session bound to the snapshot `createSnapshot` makes from `params`, and to its one project.
425	    async fn created(mut self, params: Value) -> Result<Rpc, CallError> {
426	        let response: SnapshotResponse = decode(&self.call("createSnapshot", params).await?)?;
427	        let project = response
428	            .projects
429	            .into_iter()
430	            .next()
431	            .ok_or_else(|| CallError::Rejected("createSnapshot returned no project".to_string()))?;
432	        self.snapshot = response.snapshot;
433	        self.project = project.id;
434	        Ok(self)
435	    }
