441	    /// The recorded calls as a JSON array, or `None` when recording was off.
442	    pub(crate) fn recording(&self) -> Option<Value> {
443	        let log = self.recording.as_ref()?.lock().ok()?;
444	        Some(Value::Array(log.clone()))
445	    }
446	
447	    /// Requests sent so far, by method.
448	    pub(crate) fn calls(&self) -> BTreeMap<String, u64> {
449	        self.calls.lock().map(|calls| calls.clone()).unwrap_or_default()
450	    }
