313	    /// Initializes the `tsc` session and reads the compiler options, once per process. The beta panics on
314	    /// string-valued enum options such as `target: "es2022"`, so options come from `parseConfigFile`, which yields
315	    /// numeric ones.
316	    pub(crate) async fn prepare(
317	        client: &Client,
318	        deadline: Duration,
319	        tsconfig: Option<&str>,
320	    ) -> Result<Value, CallError> {
321	        let rpc = Rpc {
322	            client: client.clone(),
323	            deadline,
324	            snapshot: 0,
325	            project: String::new(),
326	            options: Value::Null,
327	            recording: None,
328	            calls: Arc::default(),
329	        };
330	        rpc.call("initialize", Value::Null).await?;
331	        Ok(match tsconfig {
332	            Some(file) => {
333	                let parsed: Value = decode(&rpc.call("parseConfigFile", json!({ "file": file })).await?)?;
334	                parsed.get("options").cloned().unwrap_or_else(default_options)
335	            }
336	            None => default_options(),
337	        })
338	    }
