452	    /// One request, its answer as the JSON text it arrived as: [`decode`] parses it once, into the shape the caller
453	    /// expects.
454	    async fn call(&self, method: &str, params: Value) -> Result<Box<RawValue>, CallError> {
455	        if let Ok(mut calls) = self.calls.lock() {
456	            *calls.entry(method.to_string()).or_default() += 1;
457	        }
458	        REQUESTS.try_with(|count| count.fetch_add(1, std::sync::atomic::Ordering::Relaxed)).ok();
459	        let Some(log) = &self.recording else {
460	            return Ok(self.client.request_raw(method, params, self.deadline).await.map_err(classify)?.result);
461	        };
462	        let answer = self.client.request_raw(method, params.clone(), self.deadline).await.map_err(classify)?;
463	        let result: Value = decode(&answer.result)?;
464	        if let Ok(mut log) = log.lock() {
465	            log.push(json!({ "method": method, "params": params, "result": result }));
466	        }
467	        Ok(answer.result)
468	    }
