474	    /// A request about this snapshot and project, its answer left as text.
475	    async fn scoped_text(&self, method: &str, extra: Value) -> Result<Box<RawValue>, CallError> {
476	        let mut params = json!({ "snapshot": self.snapshot, "project": self.project });
477	        if let (Some(base), Value::Object(extra)) = (params.as_object_mut(), extra) {
478	            base.extend(extra);
479	        }
480	        self.call(method, params).await
481	    }
